      genState,
      setGenState,
      genImgState,
      setGenImgState,
      imgModel,
      setImgModel,
      imgLoras,
      setImgLoras,
      imgAdv,
      setImgAdv,
      modelDefaults,
      setModelDefaults,
      genEditState,
      setGenEditState,
      genRefState,
      setGenRefState,
      genFixState,
      setGenFixState,
