  function useExportPipeline(project, thumbs) {
    const [seq3, setSeq] = useState2(null);
    const [seqMix, setSeqMix] = useState2(null);
    const [edlView, setEdlView] = useState2(null);
    const [edlBusy, setEdlBusy] = useState2(false);
    const [exp, setExp] = useState2(null);
    const exportPoll = useRef2(null);
    const download = (text, name, type) => {
      const url = URL.createObjectURL(new Blob([text], { type }));
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      a.click();
      setTimeout(() => URL.revokeObjectURL(url), 1e3);
    };
    const exportAll = () => download(
      buildShotListText(project, fmt4, actLetter, shotText),
      `${project.name.replace(/\s+/g, "_")}_shotlist.txt`,
      "text/plain"
    );
    const exportJSON = () => download(JSON.stringify({ project, thumbs }, null, 2), `${project.name.replace(/\s+/g, "_")}_backup.json`, "application/json");
    const [bundling, setBundling] = useState2(false);
    const [bundleMissing, setBundleMissing] = useState2(null);
    const exportBundle = async () => {
      setBundling(true);
      try {
        const r = await fetch("/api/loom/export-bundle", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ project, thumbs })
        });
        if (!r.ok) {
          const d = await r.json().catch(() => ({}));
          alert("Bundle export failed: " + (d.error || r.status));
          return;
        }
        const report = bundleMissingReport(project, r.headers.get("X-Bundle-Missing-Count"), r.headers.get("X-Bundle-Missing"));
        const blob = await r.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `${project.name.replace(/\s+/g, "_")}_bundle.zip`;
        a.click();
        setTimeout(() => URL.revokeObjectURL(url), 1e3);
        if (report.total) setBundleMissing(report);
      } catch {
        alert("Bundle export failed -- network error.");
      } finally {
        setBundling(false);
      }
    };
    const playSequence = (entries) => {
      const clips = buildPlaySequence(entries);
      if (!clips.length) {
        alert("No finished shots yet \u2014 generate one first.");
        return;
      }
      const bed = bedOf(project);
      const segs = cutSegments(entries, project);
      setSeqMix(bed ? { bed, segs, plan: bedPlan(segs, bed) } : null);
      setSeq(clips);
    };
    const exportCut = (entries) => {
      const { clips, total } = buildExportClips(entries);
      if (!clips.length) {
        alert("No finished shots to export yet \u2014 generate one first.");
        return;
      }
      const bed = bedOf(project);
      const segs = cutSegments(entries, project);
      setExp({ status: "running", progress: 0, elapsed: 0 });
      fetch("/api/loom/export", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          clips: clips.map((c, i) => ({
            mid: c.mid,
            in: c.in,
            out: c.out,
            crop: c.crop,
            span: c.span,
            own_audio: !!(segs[i] && segs[i].ownAudio)
          })),
          total_seconds: total,
          ...bed ? { bed: { file: bed.file, db: bed.db, dur: bed.dur } } : {}
        })
      }).then((r) => r.json()).then((d) => {
        if (d.error) {
          setExp({ status: "failed", error: d.error });
          return;
        }
        const tick = () => fetch("/api/loom/export-status").then((r) => r.json()).then((s) => {
          setExp(s);
          if (s.status === "running") exportPoll.current = setTimeout(tick, 1e3);
        }).catch(() => {
          exportPoll.current = setTimeout(tick, 2e3);
        });
        tick();
      }).catch(() => setExp({ status: "failed", error: "network error" }));
    };
    const cancelExport = () => {
      fetch("/api/loom/export-cancel", { method: "POST" }).catch(() => {
      });
    };
    const closeExport = () => {
      if (exportPoll.current) clearTimeout(exportPoll.current);
      setExp(null);
    };
    const closeSequence = () => {
      setSeq(null);
      setSeqMix(null);
    };
    const openEdl = () => setEdlView({ tab: "edl" });
    const closeEdl = () => setEdlView(null);
    const exportEdl = async () => {
      const bed = bedOf(project);
      const plan = edlPlan(project, { bed });
      if (!plan.clips.length) {
        alert("No rendered shots to hand off yet \u2014 render one first.");
        return;
      }
      setEdlBusy(true);
      try {
        const r = await fetch("/api/loom/export-edl", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            csrf: await loomCsrf(),
            name: plan.slug,
            edl: plan.edl,
            csv: plan.csv,
            clips: plan.clips,
            ...bed && plan.bedName ? { bed_file: bed.file, bed_name: plan.bedName } : {}
          })
        });
        if (!r.ok) {
          const d = await r.json().catch(() => ({}));
          alert("The edit decision list didn't export: " + (d.error || r.status));
          return;
        }
        const missing = Number(r.headers.get("X-Edl-Missing-Count") || 0);
        const blob = await r.blob();
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = plan.slug + ".zip";
        a.click();
        setTimeout(() => URL.revokeObjectURL(url), 1e3);
        if (missing && window.Toast) window.Toast.show({
          kind: "err",
          title: "Exported, " + missing + " clip(s) left out",
          msg: "Their files aren't complete in your library. The zip's MISSING.txt names them."
        });
      } catch (e) {
        alert("The edit decision list didn't export \u2014 network error.");
      } finally {
        setEdlBusy(false);
      }
    };
    return {
      seq: seq3,
      seqMix,
      exp,
      playSequence,
      exportCut,
      cancelExport,
      closeExport,
      closeSequence,
      exportAll,
      exportJSON,
      exportBundle,
      bundling,
      bundleMissing,
      closeBundleMissing: () => setBundleMissing(null),
      edlView,
      setEdlView,
      openEdl,
      closeEdl,
      exportEdl,
      edlBusy
    };
  }
